import json, re

with open('/root/DATA/products/PersonalizeForce.json', 'r') as f:
    data = json.load(f)

# Keywords to search for
keywords = [
    r'competitor', r'competitive', r'compete', r'rival',
    r'strength', r'weakness', r'strengths', r'weaknesses',
    r'demo[\s_-]?url', r'demo[\s_-]?link',
    r'swot', r'benchmark', r'comparison', r'vs\b', r'versus',
    r'alternative'
]
pattern = re.compile('|'.join(keywords), re.IGNORECASE)

def search_text(text):
    return bool(pattern.search(str(text)))

def deep_search(obj):
    """Recursively search all string values in an object"""
    if isinstance(obj, str):
        return search_text(obj)
    elif isinstance(obj, dict):
        return any(deep_search(v) for v in obj.values())
    elif isinstance(obj, list):
        return any(deep_search(item) for item in obj)
    return False

print("=" * 100)
print("SECTION 1: SLACK MESSAGES")
print("=" * 100)
for i, msg in enumerate(data['slack']):
    if deep_search(msg):
        print(f"\n--- Slack message index {i} ---")
        print(json.dumps(msg, indent=2))

print("\n" + "=" * 100)
print("SECTION 2: DOCUMENTS")
print("=" * 100)
for i, doc in enumerate(data['documents']):
    if deep_search(doc):
        print(f"\n--- Document index {i} ---")
        # Print metadata first
        for k, v in doc.items():
            if k != 'content' and k != 'body':
                print(f"  {k}: {v}")
        # Print content/body
        content_key = 'content' if 'content' in doc else 'body' if 'body' in doc else None
        if content_key:
            print(f"  {content_key} (first 5000 chars):")
            print(doc[content_key][:5000])

print("\n" + "=" * 100)
print("SECTION 3: MEETING TRANSCRIPTS")
print("=" * 100)
for i, mt in enumerate(data['meeting_transcripts']):
    if deep_search(mt):
        print(f"\n--- Meeting transcript index {i} ---")
        print(json.dumps(mt, indent=2)[:8000])

print("\n" + "=" * 100)
print("SECTION 4: MEETING CHATS")
print("=" * 100)
if data['meeting_chats']:
    for i, mc in enumerate(data['meeting_chats']):
        if deep_search(mc):
            print(f"\n--- Meeting chat index {i} ---")
            print(json.dumps(mc, indent=2))
else:
    print("(empty)")

print("\n" + "=" * 100)
print("SECTION 5: URLS")
print("=" * 100)
for i, url in enumerate(data['urls']):
    if deep_search(url):
        print(f"\n--- URL index {i} ---")
        print(json.dumps(url, indent=2))

print("\n" + "=" * 100)
print("SECTION 6: PRS")
print("=" * 100)
for i, pr in enumerate(data['prs']):
    if deep_search(pr):
        print(f"\n--- PR index {i} ---")
        print(json.dumps(pr, indent=2)[:3000])
